const lines = {
  Home: ['Bakery', 'Park'],
  Bakery: ['Library', 'Zoo'],
  Park: ['Zoo'],
  Library: ['Museum'],
  Zoo: ['Museum'],
  Museum: [],
};

function bfs(start) { // breadth-first: everything 1 stop away, then 2 stops, then 3...
  const stops = new Map([[start, 0]]); // stop -> how many stops from start
  const queue = [start];
  while (queue.length > 0) {
    const stop = queue.shift();
    for (const next of lines[stop]) {
      if (!stops.has(next)) {
        stops.set(next, stops.get(stop) + 1);
        queue.push(next);
      }
    }
    console.log(`visit ${stop}, queue: ${queue.join(' ') || '(empty)'}`);
  }
  return stops;
}
const far = bfs('Home');
console.log(`Museum is ${far.get('Museum')} stops from Home`);

