function binarySearch(shelf, target) { // the shelf must be sorted!
  let lo = 0;
  let hi = shelf.length - 1;
  let looks = 0;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    looks++;
    if (shelf[mid] === target) return { index: mid, looks };
    if (shelf[mid] < target) lo = mid + 1; // too small: throw away the left half
    else hi = mid - 1; // too big: throw away the right half
  }
  return { index: -1, looks };
}

