class Branch { // one person in the family tree: smaller keys go left, bigger go right
  constructor(key) {
    this.key = key;
    this.left = null;
    this.right = null;
  }
}
function insert(node, key) {
  if (node === null) return new Branch(key);
  if (key < node.key) node.left = insert(node.left, key);
  else node.right = insert(node.right, key);
  return node;
}
function inOrder(node, out = []) { // left family, me, right family
  if (node !== null) {
    inOrder(node.left, out);
    out.push(node.key);
    inOrder(node.right, out);
  }
  return out;
}
function contains(node, key, looks = 0) {
  if (node === null) return `no (${looks} looks)`;
  if (key === node.key) return `yes (${looks + 1} looks)`;
  return contains(key < node.key ? node.left : node.right, key, looks + 1);
}
const height = (node) => (node === null ? 0 : 1 + Math.max(height(node.left), height(node.right)));

let root = null;
for (const key of [50, 30, 70, 20, 40, 60, 80]) root = insert(root, key);
console.log('in order:', inOrder(root).join(' '));
console.log('has 60?', contains(root, 60));
console.log('has 65?', contains(root, 65));
console.log('height:', height(root));

let stick = null;
for (const key of [20, 30, 40, 50, 60, 70, 80]) stick = insert(stick, key); // already sorted!
console.log('sorted input, height:', height(stick), '| has 80?', contains(stick, 80));

