// The same question without recursion: keep our own to-do stack of [node, depth] pairs.
function height(root) {
  let best = 0;
  const todo = root ? [[root, 1]] : [];
  while (todo.length > 0) {
    const [node, depth] = todo.pop();
    best = Math.max(best, depth);
    if (node.left) todo.push([node.left, depth + 1]);
    if (node.right) todo.push([node.right, depth + 1]);
  }
  return best;
}
