let calls = 0;
function fib(n) { // the plain recipe: asks the same questions again and again
  calls++;
  return n < 2 ? n : fib(n - 1) + fib(n - 2);
}
function fibMemo(n, memo = new Map()) { // the same recipe with a notebook of answers
  calls++;
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n);
  const value = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, value);
  return value;
}

for (const n of [10, 20, 30]) {
  calls = 0;
  const value = fib(n);
  const plain = calls;
  calls = 0;
  fibMemo(n);
  console.log(`fib(${n}) = ${value}: plain ${plain.toLocaleString('en-US')} calls, memo ${calls} calls`);
}

