// A hash map from scratch: a row of numbered lockers, each holding a little list (a bucket).
class LockerMap {
  constructor(lockers = 4) {
    this.buckets = Array.from({ length: lockers }, () => []);
    this.size = 0;
  }
  hash(key) { // turn any key into a locker number
    let h = 0;
    for (const ch of String(key)) h = (h * 31 + ch.codePointAt(0)) % 1_000_003;
    return h % this.buckets.length;
  }
  set(key, value) {
    const bucket = this.buckets[this.hash(key)];
    const entry = bucket.find(([k]) => k === key);
    if (entry) entry[1] = value; // same key: replace the value
    else {
      bucket.push([key, value]); // new key: add it (maybe next to others: a collision)
      this.size++;
      if (this.size / this.buckets.length > 0.75) this.grow();
    }
  }
  get(key) {
    const entry = this.buckets[this.hash(key)].find(([k]) => k === key);
    return entry ? entry[1] : undefined;
  }
  grow() { // too full: twice the lockers, and every entry moves to its new locker
    const all = this.buckets.flat();
    console.log(`  (grow: ${this.buckets.length} -> ${this.buckets.length * 2} lockers)`);
    this.buckets = Array.from({ length: this.buckets.length * 2 }, () => []);
    for (const [k, v] of all) this.buckets[this.hash(k)].push([k, v]);
  }
  show() {
    this.buckets.forEach((b, i) => console.log(`  locker ${i}: ${b.map(([k, v]) => `${k}=${v}`).join(', ') || '-'}`));
  }
}

const coats = new LockerMap();
for (const [name, coat] of [['Ada', 'red'], ['Bo', 'blue'], ['Lu', 'green']]) coats.set(name, coat);
coats.show();
coats.set('Hal', 'black');
coats.show();
