class Clue {
  constructor(value, next = null) {
    this.value = value;
    this.next = next; // the next clue, or null at the end of the hunt
  }
}

class ClueChain {
  head = null;
  size = 0;
  prepend(value) {
    this.head = new Clue(value, this.head);
    this.size++;
  }
  append(value) {
    const clue = new Clue(value);
    if (this.head === null) this.head = clue;
    else {
      let cur = this.head;
      while (cur.next !== null) cur = cur.next; // walk to the last clue
      cur.next = clue;
    }
    this.size++;
  }
  insertAfter(target, value) {
    let cur = this.head;
    while (cur !== null && cur.value !== target) cur = cur.next;
    if (cur === null) return false;
    cur.next = new Clue(value, cur.next);
    this.size++;
    return true;
  }
  toString() {
    const parts = [];
    for (let cur = this.head; cur !== null; cur = cur.next) parts.push(cur.value);
    return [...parts, 'null'].join(' -> ');
  }
}

const hunt = new ClueChain();
hunt.append('oak tree');
hunt.append('fountain');
hunt.prepend('front gate');
