// Count the steps instead of timing them: the same count on every computer, every run.
function countArray(orders, soldOut) {
  let steps = 0;
  for (const order of orders) {
    for (const dish of soldOut) { // what includes() does inside: look at each item in turn
      steps++;
      if (dish === order) break;
    }
  }
  return steps;
}
function countSet(orders, soldOut) {
  let steps = 0;
  const rack = new Set();
  for (const dish of soldOut) { rack.add(dish); steps++; } // build the rack once
  for (const order of orders) { rack.has(order); steps++; } // then one grab per order
  return steps;
}
const show = (x) => x.toLocaleString('en-US');
for (const n of [10, 100, 1000, 10000]) {
  const orders = Array.from({ length: n }, (_, i) => i); // dishes 0 .. n-1
  const soldOut = Array.from({ length: n }, (_, i) => n + i); // none of them was ordered
  console.log(`n=${show(n)}: array ${show(countArray(orders, soldOut))} steps, Set ${show(countSet(orders, soldOut))} steps`);
}

