// A queue that never moves anybody: it just remembers where the front is.
class Queue {
  #items = [];
  #head = 0;
  enqueue(x) {
    this.#items.push(x);
  }
  dequeue() {
    if (this.#head === this.#items.length) return undefined;
    const x = this.#items[this.#head];
    this.#items[this.#head] = undefined; // let go of the served item
    this.#head++;
    return x;
  }
  get size() {
    return this.#items.length - this.#head;
  }
}

const q = new Queue();
q.enqueue('Ada');
q.enqueue('Bo');
q.enqueue('Cy');
