// Count comparisons (not milliseconds) on the same shuffled numbers every run.
function shuffled(n) {
  let seed = 42;
  const rand = () => (seed = (seed * 1103515245 + 12345) % 2 ** 31) / 2 ** 31;
  return Array.from({ length: n }, () => Math.floor(rand() * 1_000_000));
}
function bubbleCount(a) {
  let c = 0;
  for (let pass = 1; pass < a.length; pass++)
    for (let i = 0; i < a.length - pass; i++) {
      c++;
      if (a[i] > a[i + 1]) [a[i], a[i + 1]] = [a[i + 1], a[i]];
    }
  return c;
}
function mergeCount(a) {
  let c = 0;
  const sort = (arr) => {
    if (arr.length <= 1) return arr;
    const mid = Math.floor(arr.length / 2), l = sort(arr.slice(0, mid)), r = sort(arr.slice(mid)), out = [];
    let i = 0, j = 0;
    while (i < l.length && j < r.length) { c++; out.push(l[i] <= r[j] ? l[i++] : r[j++]); }
    return [...out, ...l.slice(i), ...r.slice(j)];
  };
  sort(a);
  return c;
}
function builtinCount(a) {
  let c = 0;
  a.sort((x, y) => { c++; return x - y; });
  return c;
}
const show = (x) => x.toLocaleString('en-US').padStart(12);
console.log('       n      bubble       merge    built-in');
for (const n of [10, 100, 1000, 10000]) {
  console.log(String(n).padStart(8) + show(bubbleCount(shuffled(n))) + show(mergeCount(shuffled(n))) + show(builtinCount(shuffled(n))));
}

