function throttle(fn, wait) {
  let last = -Infinity;
  return (...args) => {
    const now = Date.now();
    if (now - last >= wait) {
      last = now;
      fn(...args);
    }
  };
}

const redraw = throttle((y) => console.log(`  redraw at y=${y} (t=${Date.now()} ms)`), 100);
let events = 0;
for (let y = 0; y <= 300; y += 30) { // a scroll event every 30 ms
