import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';

if (isMainThread) {
  console.log('main: hiring a helper cook for the long job');
  const helper = new Worker(new URL(import.meta.url), { workerData: 100_000_000 });
  setTimeout(() => console.log('main: doorbell answered while the helper works'), 0);
  const total = await new Promise((resolve, reject) => {
    helper.once('message', resolve);
    helper.once('error', reject);
  });
  console.log(`main: the helper says ${total}`);
} else {
  let total = 0; // this part runs on the helper's own thread
  for (let i = 0; i < workerData; i++) total += i % 7;
  parentPort.postMessage(total);
}
